// src/backend/qr.ts
async function processQr(accountId, url) {
  const qr2 = await BackendRemote.rpc.checkQr(accountId, url);
  if (!qr2) {
    throw new Error("Could not parse string");
  }
  return {
    qr: qr2,
    url
  };
}

