function archiveStateMenu(unselectChat, accountId, chat, tx, isTheSelectedChat) {
  const archive = {
    label: tx("menu_archive_chat"),
    action: () => {
      BackendRemote.rpc.setChatVisibility(accountId, chat.id, "Archived");
      if (isTheSelectedChat) {
        unselectChat();
      }
    }
  };
  const unArchive = {
    label: tx("menu_unarchive_chat"),
    action: () => {
      BackendRemote.rpc.setChatVisibility(accountId, chat.id, "Normal");
      if (isTheSelectedChat) {
        unselectChat();
      }
    }
  };
  const pin = {
    label: tx("pin_chat"),
    action: () => {
      BackendRemote.rpc.setChatVisibility(accountId, chat.id, "Pinned");
      if (chat.isArchived) {
        unselectChat();
      }
    }
  };
  const unPin = {
    label: tx("unpin_chat"),
    action: () => BackendRemote.rpc.setChatVisibility(accountId, chat.id, "Normal")
  };
  if (chat.isPinned) {
    return { pin: unPin, archive };
  } else if (chat.isArchived) {
    return { pin, archive: unArchive };
  } else {
    return { pin, archive };
  }
}
