// src/deviceMessages.ts
async function updateDeviceChat(accountId, skipCurrentChangelog = false) {
  const addDeviceMessage = async (label, msg) => {
    if (skipCurrentChangelog) {
      await BackendRemote.rpc.addDeviceMessage(accountId, label, null);
    } else {
      await BackendRemote.rpc.addDeviceMessage(accountId, label, {
        text: null,
        html: null,
        viewtype: null,
        file: null,
        filename: null,
        location: null,
        overrideSenderName: null,
        quotedMessageId: null,
        quotedText: null,
        ...msg
      });
    }
  };
  await addDeviceMessage("changelog-version-1.58.0", {
    text: `What's new in 1.58.0?

  \u{1F3A4} voice messages: finally you can record and send voice messages with DC desktop
  \u{1F464} profile view dialog redesign
  \u{1F4A1} show user names instead of mail address in many places
  \u{1F305} improved image rendering

+ MORE \u2728 improvements and \u{1F41C} bug fixes see [Full Changelog](https://github.com/deltachat/deltachat-desktop/blob/main/CHANGELOG.md#1_58_0)`
  });
}
async function updateDeviceChats() {
  const selectedAccount = await BackendRemote.rpc.getSelectedAccountId();
  for (const accountId of await BackendRemote.rpc.getAllAccountIds()) {
    await updateDeviceChat(accountId, false);
    if (accountId !== selectedAccount) {
      const devChatId = await getDeviceChatId(accountId);
      if (devChatId) markChatAsSeen(accountId, devChatId);
    }
  }
}

